-- ===========================================================================
-- TABELA SUPABASE: unidades_escolares (Sincronizada via Links Google Maps)
-- Rede Municipal de Educação de Itaguaí - 2026
-- ===========================================================================

CREATE TABLE IF NOT EXISTS unidades_escolares (
    id BIGINT PRIMARY KEY,
    inep VARCHAR(20),
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255),
    director VARCHAR(255),
    phone VARCHAR(50),
    ramal VARCHAR(20),
    street VARCHAR(255),
    number VARCHAR(50),
    complement VARCHAR(255),
    neighborhood VARCHAR(100),
    city VARCHAR(100) DEFAULT 'Itaguaí',
    state VARCHAR(2) DEFAULT 'RJ',
    cep VARCHAR(20),
    full_address TEXT,
    latitude NUMERIC(10, 7),
    longitude NUMERIC(10, 7),
    maps_link TEXT,
    modality VARCHAR(100),
    school_type VARCHAR(100),
    active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);


-- Índices para performance
CREATE INDEX IF NOT EXISTS idx_unidades_inep ON unidades_escolares(inep);
CREATE INDEX IF NOT EXISTS idx_unidades_bairro ON unidades_escolares(neighborhood);
CREATE INDEX IF NOT EXISTS idx_unidades_coords ON unidades_escolares(latitude, longitude);